const char* getNamedResource (const char* resourceNameUTF8, int& numBytes);
const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0x47775bae:  numBytes = 1607; return midi_stuff_xml;
        case 0x34bc1021:  numBytes = 1235; return LICENSE;
        case 0x64791dc8:  numBytes = 40; return README_md;
        case 0xcd63ec76:  numBytes = 926107; return mid_point_flt_typo_absa_should_be_absb_png;
        case 0x2d91b3f2:  numBytes = 325251; return mid_point_ptr_png;
        case 0xe38355c3:  numBytes = 501223; return mid_point_png;
        case 0x6672fe4b:  numBytes = 704; return generate_bat;
        case 0xceff0fcc:  numBytes = 66; return generate_fsm_bat;
        case 0x4842b068:  numBytes = 71; return generate_largest_bat;
        case 0x87155a20:  numBytes = 88; return generate_message_packet_bat;
        case 0xb5375c61:  numBytes = 88; return generate_message_router_bat;
        case 0x8f1fa17f:  numBytes = 73; return generate_smallest_bat;
        case 0x87ecc72b:  numBytes = 79; return generate_type_lookup_bat;
        case 0xd7bac1ad:  numBytes = 79; return generate_type_select_bat;
        case 0xcd5e2056:  numBytes = 80; return generate_type_traits_bat;
        case 0xcd5c0176:  numBytes = 81; return generate_variant_pool_bat;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

